def primes_in_range(low: int, high: int) -> list[int]:
    if high < 2:
        return []
    sieve = [True] * (high + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(high**0.5) + 1):
        if sieve[i]:
            for j in range(i * i, high + 1, i):
                sieve[j] = False
    return [p for p in range(max(2, low), high + 1) if sieve[p]]
